Here's a complete Account Settings screen for React Native, built with core components only (no third-party deps needed), using `Alert.alert` for the native-feeling destructive confirmation on both iOS and Android.

```tsx
// AccountSettingsScreen.tsx
import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  Image,
  ScrollView,
  Pressable,
  Switch,
  Alert,
  ActivityIndicator,
  StyleSheet,
  SafeAreaView,
  Platform,
} from 'react-native';

type NavigationRow = {
  id: string;
  type: 'navigation';
  label: string;
  value?: string;
  destructive?: boolean;
  onPress: () => void;
};

type ToggleRow = {
  id: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onValueChange: (value: boolean) => void;
};

type SettingsRow = NavigationRow | ToggleRow;

interface Profile {
  name: string;
  email: string;
  avatarUrl?: string;
}

interface AccountSettingsScreenProps {
  profile: Profile;
  onEditProfile: () => void;
  onDeleteAccount: () => Promise<void>;
}

const Chevron = () => <Text style={styles.chevron}>{'\u203A'}</Text>;

function ProfileRow({
  profile,
  onPress,
}: {
  profile: Profile;
  onPress: () => void;
}) {
  const initials = profile.name
    .split(' ')
    .map((part) => part[0])
    .slice(0, 2)
    .join('')
    .toUpperCase();

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile, ${profile.name}`}
      style={({ pressed }) => [
        styles.profileRow,
        pressed && styles.rowPressed,
      ]}
    >
      {profile.avatarUrl ? (
        <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
      ) : (
        <View style={styles.avatarFallback}>
          <Text style={styles.avatarFallbackText}>{initials}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={styles.profileName} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text style={styles.profileEmail} numberOfLines={1}>
          {profile.email}
        </Text>
      </View>
      <Chevron />
    </Pressable>
  );
}

function SettingsRowItem({ row }: { row: SettingsRow }) {
  if (row.type === 'toggle') {
    return (
      <View style={styles.row} accessibilityRole="none">
        <Text style={styles.rowLabel}>{row.label}</Text>
        <Switch
          value={row.value}
          onValueChange={row.onValueChange}
          accessibilityLabel={row.label}
          accessibilityRole="switch"
        />
      </View>
    );
  }

  return (
    <Pressable
      onPress={row.onPress}
      accessibilityRole="button"
      accessibilityLabel={row.label}
      style={({ pressed }) => [styles.row, pressed && styles.rowPressed]}
    >
      <Text style={[styles.rowLabel, row.destructive && styles.destructiveText]}>
        {row.label}
      </Text>
      {row.value ? <Text style={styles.rowValue}>{row.value}</Text> : null}
      {!row.destructive && <Chevron />}
    </Pressable>
  );
}

function Separator() {
  return <View style={styles.separator} />;
}

export default function AccountSettingsScreen({
  profile,
  onEditProfile,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const [notificationsEnabled, setNotificationsEnabled] = useState(true);
  const [faceIdEnabled, setFaceIdEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete Account',
      'This will permanently delete your account and all associated data. This action cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDeleteAccount();
            } catch (error) {
              Alert.alert(
                'Something went wrong',
                'We couldn\u2019t delete your account. Please try again.',
              );
            } finally {
              setIsDeleting(false);
            }
          },
        },
      ],
      { cancelable: true },
    );
  }, [onDeleteAccount]);

  const accountRows: SettingsRow[] = [
    {
      id: 'security',
      type: 'navigation',
      label: 'Password & Security',
      onPress: () => {},
    },
    {
      id: 'notifications',
      type: 'toggle',
      label: 'Push Notifications',
      value: notificationsEnabled,
      onValueChange: setNotificationsEnabled,
    },
    {
      id: 'biometrics',
      type: 'toggle',
      label: Platform.OS === 'ios' ? 'Face ID / Touch ID' : 'Fingerprint Unlock',
      value: faceIdEnabled,
      onValueChange: setFaceIdEnabled,
    },
  ];

  const supportRows: SettingsRow[] = [
    {
      id: 'help',
      type: 'navigation',
      label: 'Help Center',
      onPress: () => {},
    },
    {
      id: 'privacy',
      type: 'navigation',
      label: 'Privacy Policy',
      onPress: () => {},
    },
    {
      id: 'terms',
      type: 'navigation',
      label: 'Terms of Service',
      onPress: () => {},
    },
  ];

  return (
    <SafeAreaView style={styles.safeArea}>
      <ScrollView
        contentContainerStyle={styles.content}
        keyboardShouldPersistTaps="handled"
      >
        <Text style={styles.sectionTitle}>Profile</Text>
        <View style={styles.card}>
          <ProfileRow profile={profile} onPress={onEditProfile} />
        </View>

        <Text style={styles.sectionTitle}>Account</Text>
        <View style={styles.card}>
          {accountRows.map((row, index) => (
            <React.Fragment key={row.id}>
              <SettingsRowItem row={row} />
              {index < accountRows.length - 1 && <Separator />}
            </React.Fragment>
          ))}
        </View>

        <Text style={styles.sectionTitle}>Support</Text>
        <View style={styles.card}>
          {supportRows.map((row, index) => (
            <React.Fragment key={row.id}>
              <SettingsRowItem row={row} />
              {index < supportRows.length - 1 && <Separator />}
            </React.Fragment>
          ))}
        </View>

        <View style={styles.card}>
          <Pressable
            onPress={handleDeleteAccount}
            disabled={isDeleting}
            accessibilityRole="button"
            accessibilityLabel="Delete account"
            accessibilityState={{ disabled: isDeleting }}
            style={({ pressed }) => [
              styles.row,
              styles.deleteRow,
              pressed && styles.rowPressed,
            ]}
          >
            {isDeleting ? (
              <ActivityIndicator color="#D92D20" />
            ) : (
              <Text style={styles.deleteText}>Delete Account</Text>
            )}
          </Pressable>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const CARD_BACKGROUND = '#FFFFFF';
const SCREEN_BACKGROUND = Platform.select({ ios: '#F2F2F7', android: '#F5F5F5' });

const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: SCREEN_BACKGROUND,
  },
  content: {
    paddingVertical: 16,
    paddingHorizontal: 16,
  },
  sectionTitle: {
