    ...Platform.select({
      ios: {
        shadowColor: '#000',
        shadowOpacity: 0.05,
        shadowRadius: 4,
        shadowOffset: { width: 0, height: 1 },
      },
      android: {
        elevation: 1,
      },
    }),
  },
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 14,
    paddingHorizontal: 16,
  },
  avatar: {
    width: 52,
    height: 52,
    borderRadius: 26,
    marginRight: 14,
  },
  avatarFallback: {
    width: 52,
    height: 52,
    borderRadius: 26,
    marginRight: 14,
    backgroundColor: '#4F46E5',
    alignItems: 'center',
    justifyContent: 'center',
  },
  avatarFallbackText: {
    color: '#FFFFFF',
    fontSize: 18,
    fontWeight: '600',
  },
  profileText: {
    flex: 1,
  },
  profileName: {
    fontSize: 17,
    fontWeight: '600',
    color: '#111827',
  },
  profileEmail: {
    fontSize: 14,
    color: '#6B7280',
    marginTop: 2,
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingVertical: 14,
    paddingHorizontal: 16,
    minHeight: 52,
  },
  rowPressed: {
    backgroundColor: Platform.select({ ios: '#F2F2F7', android: '#ECECEC' }),
  },
  rowLabel: {
    fontSize: 16,
    color: '#111827',
  },
  rowValue: {
    fontSize: 15,
    color: '#9CA3AF',
    marginRight: 6,
  },
  chevron: {
    fontSize: 20,
    color: '#C7C7CC',
    marginLeft: 8,
  },
  separator: {
    height: 1,
    backgroundColor: '#E5E7EB',
    marginLeft: 16,
  },
  deleteRow: {
    justifyContent: 'center',
  },
  destructiveText: {
    color: '#D92D20',
  },
  deleteText: {
    fontSize: 16,
    fontWeight: '600',
    color: '#D92D20',
  },
});
```

Usage:

```tsx
<AccountSettingsScreen
  profile={{ name: 'Jordan Rivera', email: 'jordan@example.com' }}
  onEditProfile={() => navigation.navigate('EditProfile')}
  onDeleteAccount={async () => {
    await api.deleteAccount();
    // e.g. sign out / reset navigation to auth stack
  }}
/>
```

Notes on the choices:
- `Alert.alert` is used for the delete confirmation because it renders as a native dialog on both platforms (UIAlertController on iOS, AlertDialog on Android) with correct destructive-button styling — no custom modal needed.
- `Pressable` instead of `TouchableOpacity`/`TouchableNativeFeedback` so press feedback works consistently cross-platform without platform branching per-row.
- `onDeleteAccount` is async with a loading state (`ActivityIndicator`, disabled press) so a slow network call can't be double-triggered and failures surface via a second alert rather than failing silently.
- Rows are typed as a discriminated union (`navigation` | `toggle`) so adding new settings rows stays type-safe.
